window.kbPageData["views/entry/k-dacec279a5e3bc0b"] = {"key":"entry/k-dacec279a5e3bc0b","state":{"route":"entry/k-dacec279a5e3bc0b"},"node":{"id":"k-dacec279a5e3bc0b","mode":"k","title":"辩证法 · 两大特征","type":"原理与机制","domain":"哲学","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"主类":["原理与机制"],"出处性质":["理论手册"],"学科":["哲学"],"来源主题":["马克思主义哲学"],"资料类别":["非时政"]},"directorySummary":"一、两大特征\n1.联系\n（1）含义：联系是指一切事物之间和事物内部各要素之间的相互依赖、相互影响、相\n互制约和相互作用。\n（2）特征：普遍性、客观性、多样性、条件性。\n（粉笔敲黑板：本考点重点要做好对四个特征的区分，常结合案例考查体现或违背联系\n的某个特征）\n（3）整体和部分的关系\n整体对部分起支配…","sources":[{"id":"3112b0a4ec0af017","label":"辩证法 · 两大特征","topic":"马克思主义哲学","category":"非时政","text":"一、两大特征\n1.联系\n（1）含义：联系是指一切事物之间和事物内部各要素之间的相互依赖、相互影响、相\n互制约和相互作用。\n（2）特征：普遍性、客观性、多样性、条件性。\n（粉笔敲黑板：本考点重点要做好对四个特征的区分，常结合案例考查体现或违背联系\n的某个特征）\n（3）整体和部分的关系\n整体对部分起支配、统率、决定的作用。\n部分影响整体，关键部分对整体起决定性作用。\n整体是各个部分的有机结合，整体具有部分所没有的新功能。\n2.发展\n（1）含义：发展是前进的、上升的运动。\n（2）实质：发展的实质是新事物的产生和旧事物的灭亡。\n新旧事物区别的根本标志：是否同事物发展的必然趋势相符合。\n（粉笔敲黑板：判断一个事物是新事物还是旧事 物，并不取决于其形式的新旧与出现\n时间的先后）\n3.联系和发展具有规律性\n规律是客观存在的，是不以人的意志为转移的。","source":{"doc":"3ccc56f4000d1642c2d1","first":2,"last":3,"page":2,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"questions":{},"terms":{},"references":{},"topics":[],"units":{"k-dacec279a5e3bc0b":[]}};
